style.css:
@-moz-document domain("youtube.com") {
/* MAIN BACKGROUND */
  body, ytd-app, #content, #container, #page-manager {
    background-color: #ffe6f2 !important;
  }

  /* HEADER / TOP BAR */
  ytd-masthead {
    background-color: #ffb3d9 !important;
    border-bottom: 2px solid #ff66b3 !important;
  }

  /* SEARCH BAR */
  #search, #search-input input {
    background-color: #ffe6f2 !important;
    color: #660033 !important;
    border: 1px solid #ff99cc !important;
  }

  #search-icon-legacy {
    background-color: #ff99cc !important;
  }

  /* SIDEBAR */
  ytd-guide-renderer {
    background-color: #ffd6e8 !important;
  }

  ytd-guide-entry-renderer:hover {
    background-color: #ffb3d9 !important;
  }

  /* VIDEO TITLES */
  #video-title {
    color: #99004d !important;
  }

  /* LINKS / TEXT COLORS */
  a, yt-formatted-string, .yt-simple-endpoint {
    color: #cc0077 !important;
  }

  /* SUBSCRIBE BUTTON */
  ytd-subscribe-button-renderer button {
    background-color: #ff66b3 !important;
    color: white !important;
    border-radius: 8px !important;
  }

  ytd-subscribe-button-renderer button:hover {
    background-color: #ff1a8c !important;
  }

  /* LIKE / SHARE BUTTONS */
  ytd-toggle-button-renderer button {
    background-color: #ffcce6 !important;
    border-radius: 6px !important;
  }

  ytd-toggle-button-renderer button:hover {
    background-color: #ff99cc !important;
  }

  /* COMMENTS SECTION */
  #comments {
    background-color: #ffe6f2 !important;
  }

  #content-text {
    color: #660033 !important;
  }

  /* SCROLLBAR */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-thumb {
    background: #ff66b3 !important;
    border-radius: 8px;
  }

  ::-webkit-scrollbar-track {
    background: #ffe6f2 !important;
  }
}
